/* @catalog — generated by `npm run catalog:generate`; do not edit by hand.
 * Exports
 *   Functions: AdminVideoGridPageItem
 * Internal
 *   Types: VideoItem, VideoReview, GridPresentation
 *   Functions: VideoGridSummary
 *   Constants: SortableOrderList, reviewKey
 * @end-catalog */

import { lazy, Suspense, useEffect, useRef, useState, type ReactNode } from 'react';
import { useQuery, useQueryClient } from '@tanstack/react-query';
import { ModalDialog } from '../../components/ModalDialog';
import { ApiError } from '../../api/client';
import { useAdminAccess } from './AdminAccess';
import { useAdminPageText } from './adminPageText';
import { adminWorkspace } from './adminWorkspace';
import { adminEndpointRequest } from './adminTransport';
import { useAdminCommand } from './useAdminCommand';
import type { OrderReview } from './PageOrderList';
import { videoGridMutationResponse, videoGridResponse, type AdminVideoGrid } from './videoGridApi';

type VideoItem = AdminVideoGrid['items'][number] & { itemId: string; name: string };
// Sorting mechanics load only when the editor opens, keeping the Page summary within its route budget.
const SortableOrderList = lazy(() => import('./PageOrderList').then(module => ({ default: module.SortableOrderList<VideoItem> })));
/** Frozen review text survives navigation independently of subsequently refreshed server data. */
interface VideoReview extends OrderReview<VideoItem> { defaultView: AdminVideoGrid['defaultView']; originalView: AdminVideoGrid['defaultView'] }
const reviewKey = 'video-grid-review';
/** Shared Page presentation is supplied by the parent, avoiding a reverse dependency on its route bundle. */
interface GridPresentation { styles: Record<string, string>; gridIcon: (size: number) => ReactNode }

/** Presents the complete approved order for confirmation and exact-operation recovery. */
function VideoGridSummary({ review, label, styles, gridIcon }: GridPresentation & { review: VideoReview; label: string }) {
  const t = useAdminPageText();
  return <>
    <p className={styles.definitionScope}>{t('pages.video_default')}: <strong>{t('pages.video_' + review.defaultView)}</strong></p>
    <ol className={styles.orderSummary} aria-label={label}>{review.items.map((item, index) => <li key={item.id}>
      <span className={styles.position}>{index + 1}</span>{gridIcon(17)}
      <span className={styles.summaryName}>{item.title}</span>
    </li>)}</ol>
  </>;
}

/** Configures one Video Grid without allowing synthetic Page visibility or placement writes. */
export default function AdminVideoGridPageItem({ metadata, visibility, gridIcon, styles, onEditing }: GridPresentation & {
  metadata: ReactNode; visibility: ReactNode; onEditing: (value: boolean) => void;
}) {
  const t = useAdminPageText(), access = useAdminAccess(), client = useQueryClient();
  const queryKey = ['admin-imports', access.viewerId, access.epoch, access.generation, 'video-grid'];
  const query = useQuery({ queryKey, queryFn: ({ signal }) => adminEndpointRequest('/pages/videos/grid', videoGridResponse, { signal }), retry: false, gcTime: 0 });
  const command = useAdminCommand('video-grid', videoGridMutationResponse);
  const [draft, setDraft] = useState<VideoReview | null>(null), [confirm, setConfirm] = useState(false);
  const [operation, setOperation] = useState(() => adminWorkspace.buffer<VideoReview>(reviewKey) ?? null);
  const [saved, setSaved] = useState(false), [dragging, setDragging] = useState(false);
  const opener = useRef<HTMLButtonElement>(null), saveButton = useRef<HTMLButtonElement>(null), cancelButton = useRef<HTMLButtonElement>(null), recovery = useRef<HTMLButtonElement>(null);
  const restoreFocus = useRef(false);
  const active = useRef(true), refreshAttempt = useRef(0);
  useEffect(() => { active.current = true; return () => { active.current = false; refreshAttempt.current++; }; }, []);
  useEffect(() => { onEditing(Boolean(draft)); }, [Boolean(draft), onEditing]);
  useEffect(() => {
    if (!command.result) return;
    void client.cancelQueries({ queryKey }); client.setQueryData(queryKey, { grid: command.result.grid });
    adminWorkspace.forget(reviewKey); setOperation(null); setDraft(null); setConfirm(false); setSaved(true); restoreFocus.current = true;
    command.command.acknowledge(); void query.refetch();
  }, [command.result]);
  useEffect(() => {
    if (saved && !query.isFetching && restoreFocus.current) { restoreFocus.current = false; opener.current?.focus(); }
  }, [saved, query.isFetching]);
  useEffect(() => {
    if (!command.error || !operation) return;
    setConfirm(false);
    if (command.intent || command.error === 'reload') setDraft(null);
    const timer = window.setTimeout(() => recovery.current?.focus(), 0);
    return () => window.clearTimeout(timer);
  }, [command.error, command.intent, operation]);
  const locked = command.running || Boolean(command.intent) || !access.catalogEditing || access.reloadRequired;
  const stale = Boolean(draft && (draft.revision !== query.data?.grid.revision || command.error === 'conflict'));
  const changed = Boolean(draft && (draft.defaultView !== draft.originalView || draft.items.some((entry, index) => entry.id !== draft.originalIds[index])));
  useEffect(() => { if (confirm && stale) recovery.current?.focus(); }, [confirm, stale]);

  /** Starts only from a complete confirmed snapshot, never a retained uncertain review. */
  function begin(grid: AdminVideoGrid) {
    setSaved(false); command.command.settle();
    setDraft({ revision: grid.revision, defaultView: grid.defaultView, originalView: grid.defaultView,
      originalIds: grid.items.map(entry => entry.id), items: grid.items.map(entry => ({ ...entry, itemId: entry.id, name: entry.title })) });
  }
  function cancel() {
    if (command.running || command.intent) return;
    refreshAttempt.current++; setDraft(null); setConfirm(false); setDragging(false); setOperation(null);
    adminWorkspace.forget(reviewKey); command.command.settle();
    const guard = adminWorkspace.capture();
    window.requestAnimationFrame(() => { if (active.current && adminWorkspace.current(guard)) opener.current?.focus(); });
  }
  async function restart() {
    if (command.running || command.intent) return;
    cancel(); const attempt = ++refreshAttempt.current, guard = adminWorkspace.capture();
    const result = await query.refetch();
    if (active.current && attempt === refreshAttempt.current && adminWorkspace.current(guard) && result.isSuccess) begin(result.data.grid);
  }
  const conflicts = <><button ref={recovery} type="button" className={styles.refresh} disabled={query.isFetching} onClick={cancel}>{t('pages.order_cancel')}</button>
    <button type="button" className={styles.refresh} disabled={query.isFetching || locked} onClick={() => void restart()}>{t('pages.order_restart')}</button></>;
  const refresh = <button type="button" className={styles.refresh} disabled={query.isFetching || command.running} onClick={() => { setSaved(false); void query.refetch(); }}>{t('common.refresh')}</button>;
  const renderIcon = (entry: VideoItem, size: number) => entry.coverUrl
    ? <img className={styles.videoCover} src={entry.coverUrl} alt="" loading="lazy" /> : gridIcon(size);

  return <div className={styles.videoSection}>
    <ol className={styles.list} aria-label={t('pages.order_current')}><li className={styles.placement}>
      <span className={styles.position} aria-hidden>01</span><span className={styles.typeIcon}>{gridIcon(23)}</span>
      <div className={styles.identity}><h3 aria-label={'1 · ' + t('pages.videos')}>{t('pages.videos')}</h3>{metadata}</div>
      {visibility}
      <button ref={opener} type="button" className={styles.refresh} disabled={locked || query.isFetching || query.isError || !query.data || Boolean(draft)} onClick={() => { if (query.data) begin(query.data.grid); }}>{t('pages.video_edit')}</button>
    </li></ol>
    <p className={styles.definitionScope}>{t('pages.video_copy')}</p>
    {query.isPending && <p className={styles.refreshStatus} role="status">{t('common.loading')}</p>}
    {query.isError && <div className={styles.notice} role="alert"><p>{t(query.error instanceof ApiError && query.error.code === 'ADMIN_VIDEO_GRID_CAPACITY' ? 'pages.video_capacity' : 'pages.load_error')}</p>{refresh}</div>}
    {saved && <p role="status" className={styles.refreshStatus}>{t('pages.video_saved')}</p>}
    {command.running && <p className={styles.notice} role="status">{t('pages.order_saving')}</p>}
    {command.error && <div className={styles.notice} role="alert"><div>
      <p>{t(command.intent ? 'pages.video_unknown' : command.error === 'conflict' ? 'pages.video_stale' : command.error === 'capacity' ? 'pages.order_capacity' : command.error === 'video_capacity' ? 'pages.video_capacity' : 'common.' + command.error)}</p>
      {operation && <VideoGridSummary styles={styles} gridIcon={gridIcon} review={operation} label={t('pages.order_original_list')} />}
    </div><div className={styles.noticeActions}>{command.intent ? <>{refresh}<button ref={recovery} type="button" className={styles.refresh} disabled={command.running} onClick={command.command.retry}>{t('common.retry_operation')}</button></>
      : command.error !== 'reload' && conflicts}</div></div>}
    {draft && <section className={styles.videoEditor} aria-label={t('pages.video_edit')}>
      <div className={styles.overview}><h2>{t('pages.video_edit')}</h2><p>{t('pages.order_hint')}</p></div>
      <label className={styles.videoView}>{t('pages.video_default')}<select value={draft.defaultView} disabled={locked || confirm || stale} onChange={event => setDraft(current => current && { ...current, defaultView: event.target.value as VideoReview['defaultView'] })}>
        <option value="grid">{t('pages.video_grid')}</option><option value="immersive">{t('pages.video_immersive')}</option>
      </select></label>
      {stale && !confirm && !command.error && <div role="alert" className={styles.notice}><p>{t('pages.video_stale')}</p><div className={styles.noticeActions}>{conflicts}</div></div>}
      <Suspense fallback={<p role="status">{t('common.loading')}</p>}><SortableOrderList review={draft} text={t} styles={styles} renderIcon={renderIcon} renderVisibility={() => null}
        renderMetadata={entry => entry.creator ? <p className={styles.metadata}>{entry.creator}</p> : null}
        disabled={locked || confirm || stale} onDragging={setDragging} onChange={items => setDraft(current => current && { ...current, items })} /></Suspense>
      <div className={styles.dialogActions}><button type="button" className={styles.refresh} disabled={command.running} onClick={cancel}>{t('pages.order_cancel')}</button>
        <button ref={saveButton} type="button" className={styles.refresh} disabled={locked || stale || !changed || dragging} onClick={() => setConfirm(true)}>{t('pages.order_save')}</button></div>
    </section>}
    {confirm && draft && <ModalDialog title={t('pages.video_confirm_title')} description={t('pages.video_confirm_copy')} initialFocusRef={cancelButton} returnFocusRef={saveButton}
      closeDisabled={command.running} onClose={() => setConfirm(false)}>
      <VideoGridSummary styles={styles} gridIcon={gridIcon} review={draft} label={t('pages.order_new')} /><p className={styles.definitionScope}>{t('pages.video_scope')}</p>
      {stale && <p className={styles.notice} role="alert">{t('pages.video_stale')}</p>}
      <div className={styles.dialogActions}>{stale ? conflicts : <><button ref={cancelButton} type="button" className={styles.refresh} disabled={command.running} onClick={() => setConfirm(false)}>{t('pages.order_back')}</button>
        <button type="button" className={styles.refresh + ' ' + styles.confirm} disabled={locked || !changed} onClick={() => {
          adminWorkspace.retain(reviewKey, draft, adminWorkspace.capture()); setOperation(draft);
          void client.cancelQueries({ queryKey });
          command.command.run('/pages/videos/grid', { expectedRevision: draft.revision, defaultView: draft.defaultView, videoIds: draft.items.map(entry => entry.id) }, 'PATCH', { ADMIN_VIDEO_GRID_CAPACITY: 'video_capacity', ADMIN_CATALOG_RECEIPT_LIMIT: 'capacity' });
        }}>{t(command.running ? 'pages.order_saving_button' : 'pages.order_confirm')}</button></>}</div>
    </ModalDialog>}
  </div>;
}
